 import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, color, mix, smoothstep, add, mul, sub, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    THREE: { Group, Mesh, PlaneGeometry, BoxGeometry, Shape, ExtrudeGeometry, DirectionalLight, PointLight }
  } = ctx;

  const root = new Group();
  root.name = 'bento-metrics-grid';

  const visual = config.intent?.visualSpec || {};
  const colors = visual.colors || {
    background: '#0b0b10',
    surface: '#14141a',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#101017' }, { at: 1, hex: '#1a1a22' }]
  };
  const cStops = colors.gradientStops || [];
  const stop0 = cStops[0]?.hex || '#101017';
  const stop1 = cStops[1]?.hex || '#1a1a22';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';

  const timelines = [];

  function killAll() {
    timelines.forEach((tl) => tl?.kill && tl.kill());
    timelines.length = 0;
  }

  const u = uv();
  const t = clamp(mul(add(u.x, u.y), 0.5), 0.0, 1.0);
  const baseGrad = mix(color(stop0), color(stop1), t);
  const sheen = mul(
    smoothstep(0.36, 0.4, t),
    smoothstep(0.44, 0.4, t)
  );
  const gradientNode = add(baseGrad, mul(sheen, vec3(0.06)));

  const capMaterial = new MeshPhysicalNodeMaterial({
    colorNode: gradientNode,
    roughness: 0.5,
    metalness: 0.45,
    clearcoat: 0.2
  });

  const edgeMaterial = new MeshStandardNodeMaterial({
    color: colors.surface || '#14141a',
    roughness: 0.5,
    metalness: 0.45,
    clearcoat: 0.2
  });

  const tickMaterial = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.3,
    roughness: 1.0,
    metalness: 0.0
  });

  function createCell(w, h, x, y, z) {
    const shape = new Shape();
    shape.moveTo(0, 0);
    shape.lineTo(w, 0);
    shape.lineTo(w, h);
    shape.lineTo(0, h);
    shape.lineTo(0, 0);

    const geom = new ExtrudeGeometry(shape, {
      depth: 0.06,
      bevelEnabled: true,
      bevelSize: 0.04,
      bevelThickness: 0.04,
      bevelSegments: 2
    });
    geom.center();

    const cellMesh = new Mesh(geom, [edgeMaterial, capMaterial]);
    cellMesh.position.set(x, y, z);
    cellMesh.castShadow = false;

    return cellMesh;
  }

  function createTickBar(x, y, z) {
    const tick = new Mesh(new BoxGeometry(0.4, 0.05, 0.01), tickMaterial);
    tick.position.set(x, y, z);
    return tick;
  }

  function createText(str, size, col, x, y, z, align = 'left') {
    const label = ctx.fontAtlas.createText(str, {
      fontSize: size,
      color: col,
      align: align
    });
    label.position.set(x, y, z);
    return label;
  }

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    new MeshBasicNodeMaterial({
      colorNode: mix(color(stop0), color(stop1), uv().y)
    })
  );
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const rim = new DirectionalLight(accent, 0.65);
  rim.position.set(-3, 4, 4);
  root.add(rim);

  const fill = new PointLight(paper, 0.4, 12);
  fill.position.set(2, -1, 3);
  root.add(fill);

  const gridGroup = new Group();
  root.add(gridGroup);

  const domX = -1.125;
  const domY = 0;
  const domCell = new Group();
  domCell.position.set(domX, domY, 0);
  const domMesh = createCell(3.25, 3.5, 0, 0, 0);
  domCell.add(domMesh);
  domCell.add(createTickBar(-1.225, 1.225, 0.06));
  domCell.add(createText('0.002 mm', 0.62, paper, -1.225, 0.1, 0.06, 'left'));
  domCell.add(createText('Case tolerance, CNC pass', 0.09, paper, -1.225, -0.4, 0.06, 'left'));
  gridGroup.add(domCell);

  const rightTopCell = new Group();
  rightTopCell.position.set(1.75, 0.9375, 0);
  rightTopCell.add(createCell(2.0, 1.625, 0, 0, 0));
  rightTopCell.add(createTickBar(-0.55, 0.7125, 0.06));
  rightTopCell.add(createText('38 h', 0.34, paper, -0.55, 0.35, 0.06, 'left'));
  rightTopCell.add(createText('Power reserve, NA-01', 0.09, paper, -0.55, -0.15, 0.06, 'left'));
  gridGroup.add(rightTopCell);

  const rightBottomCell = new Group();
  rightBottomCell.position.set(1.75, -0.9375, 0);
  rightBottomCell.add(createCell(2.0, 1.625, 0, 0, 0));
  rightBottomCell.add(createTickBar(-0.55, 0.7125, 0.06));
  rightBottomCell.add(createText('214', 0.34, paper, -0.55, 0.35, 0.06, 'left'));
  rightBottomCell.add(createText('Components per calibre', 0.09, paper, -0.55, -0.15, 0.06, 'left'));
  gridGroup.add(rightBottomCell);

  const caption = createText('ATELIER METRICS / Q2 2026', 0.09, paper, -2.75, 2.25, 0, 'left');
  root.add(caption);

  const cellGroups = [domCell, rightTopCell, rightBottomCell];

  function addHover(group) {
    const handlers = {};
    handlers.pointerenter = () => {
      timelines.forEach((tl) => {
        if (tl?._target === group) tl.kill();
      });
      const tl = gsap.timeline({ _target: group });
      tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.275)' });
      timelines.push(tl);
    };
    handlers.pointerleave = () => {
      timelines.forEach((tl) => {
        if (tl?._target === group) tl.kill();
      });
      const tl = gsap.timeline({ _target: group });
      tl.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.18, ease: 'power2.out' })
        .to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.72, ease: 'power4.out' });
      timelines.push(tl);
    };
    group.userData.handlers = handlers;
  }

  cellGroups.forEach(addHover);

  const entranceTl = gsap.timeline();
  cellGroups.forEach((g, i) => {
    g.visible = true;
    const baseZ = g.position.z;
    g.position.y += 0.2;
    g.scale.set(1, 1, 1);
    const mesh = g.children.find((c) => c.isMesh && c.material);
    if (mesh) {
      mesh.material.transparent = true;
      mesh.material.opacity = 0;
      mesh.material.needsUpdate = true;
    }
  });

  cellGroups.forEach((g, i) => {
    const delay = i * 0.08;
    const mesh = g.children.find((c) => c.isMesh && c.material);
    const targetOpacity = 1;
    const targetY = g.position.y - 0.2;
    const props = { y: targetY, opacity: targetOpacity };
    entranceTl.to(
      g.position,
      { y: targetY, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      delay
    );
    if (mesh) {
      entranceTl.to(
        mesh.material,
        { opacity: targetOpacity, duration: 0.5, ease: 'power2.out' },
        delay
      );
    }
  });
  timelines.push(entranceTl);

  const primitives = config.cinematicPrimitives || [];
  for (const primitive of primitives) {
    if (typeof ctx.primitives?.[primitive.name] === 'function') {
      const r = ctx.primitives[primitive.name](root, primitive.params || {});
      if (r?.timeline) timelines.push(r.timeline);
    }
  }

  root.userData.cleanup = () => {
    killAll();
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
